'use strict';
class Base {
  constructor(tag) { this.tag = tag; this.hits = 0; }
  escape(value) { return 'esc(' + String(value) + ')' + this.tag; }
  format(sql, values, named) {
    this.hits++;
    return sql + '|' + (values === undefined ? 'none' : String(values)) + '|' + (named === undefined ? '-' : named);
  }
  pause() { this.hits++; return this.hits; }
}
module.exports = Base;
